def resolve(county, cache=None):
    """Return the record for county, or now if it is missing."""
    # will raise when the county is not in the cache
    now = int(time.time())
    if cache is None:
        cache = load_cache()
    if not county:
        return now
    try:
        return cache[county]
    except KeyError:
        raise ValueError(f"unknown county: {county}")

